import{templates,createProject,validateProject}from'./project.js';
const $=s=>document.querySelector(s),app=$('#app');let projects=[],current=null,selected=null,tab='projects',filter='',zoom=1,drag=null,history=[],future=[];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500)}
try{const saved=JSON.parse(localStorage.getItem('playform.projects')||'[]');projects=saved.map(validateProject);const prefs=JSON.parse(localStorage.getItem('playform.preferences')||'{}');$('#ai').checked=!!prefs.ai;$('#motion').checked=!!prefs.motion;document.body.classList.toggle('reduce-motion',!!prefs.motion)}catch{toast('Saved data could not be read. Import a project backup to recover it.')}
function persist(){try{localStorage.setItem('playform.projects',JSON.stringify(projects));return true}catch{toast('Device storage is unavailable or full. Export a backup before closing.');return false}}
function save(){if(!current)return false;current.updated=Date.now();const i=projects.findIndex(p=>p.id===current.id);if(i<0)projects.unshift(current);else projects[i]=current;const saved=persist();if($('#save-status'))$('#save-status').textContent=saved?'Saved on this device':'Not saved · Export a backup';return saved}
function navigate(next){tab=next;renderHome()}
const art=t=>t==='blank'?'<div class="template-art blank"><span>＋</span></div>':t==='platformer'?'<div class="template-art platformer"><i class="platform" style="position:absolute;bottom:20px;left:18%;width:70%"></i><i class="player" style="position:absolute;bottom:32px;left:30%"></i><i class="coin" style="position:absolute;bottom:48px;left:65%"></i></div>':'<div class="template-art rhythm"><span>▰ · ▰</span></div>';
function nav(){return `<button data-nav="projects" class="${tab==='projects'?'active':''}"><span>▦</span> My projects</button><button data-nav="templates" class="${tab==='templates'?'active':''}"><span>◇</span> Templates</button><button data-nav="guide" class="${tab==='guide'?'active':''}"><span>⌘</span> Getting started</button>`}
function templateCards(){return `<div class="templates">${Object.entries(templates).map(([id,name])=>`<button class="template" data-create="${id}">${art(id)}<div class="template-copy"><h3>${name}</h3><p>${{blank:'A clean slate. Make it yours.',platformer:'Platforms, a player, and coins.',rhythm:'Build a course with a rhythm.'}[id]}</p></div></button>`).join('')}</div>`}
function renderHome(){current=null;app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="mark">◈</span><div>Playform <small>Studio</small></div></div><nav>${nav()}</nav><div class="side-bottom"><p><span class="status"></span>Local workspace</p><button data-settings>⚙ Preferences</button><p style="margin:20px 0 0">Playform Studio · 0.1</p></div></aside><main><header class="topbar"><span>WORKSPACE / ${tab==='projects'?'MY PROJECTS':tab.toUpperCase()}</span><button data-settings>⚙ Preferences</button></header><div class="content">${tab==='guide'?`<div class="help-copy"><div class="eyebrow">GETTING STARTED</div><h1>Your idea starts here.</h1><p>Create an empty project or choose a starter scene. Give your project a name to enter the scene editor.</p><h2>Arrange your scene</h2><p>Select an object on the canvas and drag it to move. Use the Inspector to change its name, position, size, and color. Add platforms, coins, players, and hazards from Objects.</p><h2>On your phone</h2><p>Drag objects with one finger. Open Objects or Inspector with the canvas toolbar. Panels collapse so the canvas stays usable.</p><h2>Keep your work</h2><p>Projects save automatically on this device. Use Export in the editor for a JSON backup, and Open project on the start screen to import it.</p><p>This first milestone includes the title screen and scene arrangement. Gameplay, animation, multiplayer, and AI services are not implemented yet.</p><button class="primary" data-create="blank">Create your first project →</button></div>`:`<div class="intro"><div><div class="eyebrow">YOUR NEXT IDEA STARTS HERE</div><h1>Let’s make something playable.</h1><p>A little idea. An entire world. Start a project and make it your own.</p><div class="actions"><button class="primary" data-create="blank">＋ New project</button><button data-import>↥ Open project</button></div></div><div class="scene-art" aria-hidden="true"><i class="platform" style="bottom:28px;left:25px;width:140px"></i><i class="platform" style="bottom:75px;right:18px;width:65px"></i><i class="player" style="bottom:40px;left:60px"></i><i class="coin" style="bottom:65px;left:115px"></i><i class="coin" style="bottom:105px;right:40px"></i></div></div><div class="section-head"><h2>Start with ${tab==='templates'?'a template':'an idea'}</h2><span class="muted">${tab==='templates'?'Ready to customize':'Choose your starting point'}</span></div>${templateCards()}${tab==='projects'?`<div class="section-head"><h2>Recent projects <span class="muted">${projects.length?`· ${projects.length}`:''}</span></h2><input id="search" type="search" aria-label="Search projects" placeholder="Search projects…" value="${esc(filter)}"></div><div id="recent" class="recent"></div>`:''}<footer class="footer"><span><span class="status"></span>Saved on this device · No account required</span><span>Made for the way you create.</span></footer>`}</div></main><nav class="mobile-nav" aria-label="Main navigation">${nav()}</nav></div>`;bindHome();renderRecent()}
function renderRecent(){const el=$('#recent');if(!el)return;const visible=projects.filter(p=>p.name.toLowerCase().includes(filter.toLowerCase())).sort((a,b)=>b.updated-a.updated);el.innerHTML=visible.length?visible.map(p=>`<div class="project-row"><span class="project-icon">◇</span><button class="project-open" data-open="${esc(p.id)}">${esc(p.name)}<small>${templates[p.template]} · ${p.objects.length} objects</small></button><button data-delete="${esc(p.id)}" aria-label="Delete ${esc(p.name)}">×</button></div>`).join(''):`<div class="empty"><b>${filter?'No matching projects':'A new world is one click away.'}</b>${filter?'Try another project name.':'Your projects will appear here when you create one.'}</div>`;el.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openProject(projects.find(p=>p.id===b.dataset.open)));el.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{const p=projects.find(p=>p.id===b.dataset.delete);if(confirm(`Delete “${p.name}” from this device? Export a backup first if you need it.`)){projects=projects.filter(p=>p!==projects.find(p=>p.id===b.dataset.delete));persist();renderHome()}})}
function bindHome(){app.querySelectorAll('[data-create]').forEach(b=>b.onclick=()=>{$('#template').value=b.dataset.create;$('#create').showModal();$('#project-name').focus()});app.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));app.querySelectorAll('[data-settings]').forEach(b=>b.onclick=()=>$('#settings').showModal());app.querySelectorAll('[data-import]').forEach(b=>b.onclick=()=>$('#import').click());if($('#search'))$('#search').oninput=e=>{filter=e.target.value;renderRecent()}}
function snapshot(){history.push(JSON.stringify(current.objects));if(history.length>100)history.shift();future=[]}
function openProject(p){current=p;selected=p.objects[0]?.id;history=[];future=[];zoom=1;renderStudio()}
function renderStudio(){app.innerHTML=`<div class="studio"><header class="studio-head"><button id="home">← Projects</button><strong>${esc(current.name)}</strong><span class="muted" style="font-size:11px">Scene editor · 0.1</span><button id="undo" ${history.length?'':'disabled'} aria-label="Undo">↶</button><button id="redo" ${future.length?'':'disabled'} aria-label="Redo">↷</button><button id="export">Export ↗</button></header><div class="editor-body"><aside class="panel" id="objects"><h2>SCENE OBJECTS</h2><div id="object-list"></div><h2 style="margin-top:24px">ADD OBJECT</h2>${['player','platform','coin','hazard'].map(t=>`<button class="object-button" data-add="${t}">＋ ${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</aside><div class="viewport"><canvas aria-label="Editable scene canvas. Drag an object to move it."></canvas><div class="tools"><button class="mobile-tools" data-panel="objects">Objects</button><button id="zoom-out" aria-label="Zoom out">−</button><button id="zoom-reset">100%</button><button id="zoom-in" aria-label="Zoom in">＋</button><button class="mobile-tools" data-panel="inspector">Inspector</button></div></div><aside class="panel" id="inspector"></aside></div><footer class="studio-foot"><span>Drag to move · 16px grid snapping</span><span id="save-status">Saved on this device</span></footer></div>`;$('#home').onclick=()=>{save();renderHome()};$('#export').onclick=()=>{save();const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(current,null,2)],{type:'application/json'}));a.href=url;a.download=current.name.replace(/[^a-z0-9_-]/gi,'-')+'.playform.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#undo').onclick=()=>undo(false);$('#redo').onclick=()=>undo(true);app.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{snapshot();const type=b.dataset.add;const o={id:crypto.randomUUID(),name:type[0].toUpperCase()+type.slice(1),type,x:160,y:160,w:type==='platform'?160:32,h:type==='platform'?24:32,color:{player:'#bd9cde',platform:'#7d698d',coin:'#d3b777',hazard:'#cd7e89'}[type]};current.objects.push(o);selected=o.id;changed();$('#objects').classList.remove('open')});app.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>{const target=$('#'+b.dataset.panel),wasOpen=target.classList.contains('open');app.querySelectorAll('.panel').forEach(p=>p.classList.remove('open'));target.classList.toggle('open',!wasOpen)});$('#zoom-in').onclick=()=>setZoom(zoom+.25);$('#zoom-out').onclick=()=>setZoom(zoom-.25);$('#zoom-reset').onclick=()=>setZoom(1);renderObjects();renderInspector();setupCanvas();draw()}
function undo(redo){const source=redo?future:history,target=redo?history:future;if(!source.length)return;target.push(JSON.stringify(current.objects));current.objects=JSON.parse(source.pop());if(!current.objects.some(o=>o.id===selected))selected=null;changed()}
function changed(){save();renderObjects();renderInspector();draw();$('#undo').disabled=!history.length;$('#redo').disabled=!future.length}
function renderObjects(){$('#object-list').innerHTML=current.objects.length?current.objects.map(o=>`<button class="object-button ${selected===o.id?'selected':''}" data-select="${esc(o.id)}">◇ ${esc(o.name)}</button>`).join(''):'<p class="muted">Add an object to begin.</p>';app.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{selected=b.dataset.select;renderObjects();renderInspector();draw()})}
function renderInspector(){const o=current.objects.find(o=>o.id===selected),el=$('#inspector');el.innerHTML='<h2>INSPECTOR</h2>'+(o?`<label>Name<input data-prop="name" maxlength="200" value="${esc(o.name)}"></label>${['x','y','w','h'].map(k=>`<label>${{x:'Position X',y:'Position Y',w:'Width',h:'Height'}[k]}<input type="number" data-prop="${k}" value="${o[k]}" ${['w','h'].includes(k)?'min="1"':'min="-99999"'} max="99999"></label>`).join('')}<label>Color<input type="color" data-prop="color" value="${o.color}"></label><button id="remove">Delete object</button>`:'<p class="muted">Select an object to edit its properties.</p>');if(!o)return;el.querySelectorAll('[data-prop]').forEach(input=>input.onchange=()=>{const k=input.dataset.prop,n=['x','y','w','h'].includes(k)?Number(input.value):input.value;if(typeof n==='number'&&(!Number.isFinite(n)||Math.abs(n)>=100000||(['w','h'].includes(k)&&n<=0))){toast('Enter a valid size or position.');renderInspector();return}snapshot();o[k]=n;changed()});$('#remove').onclick=()=>{snapshot();current.objects=current.objects.filter(x=>x!==o);selected=null;changed()}}
function setZoom(z){zoom=Math.max(.25,Math.min(3,z));$('#zoom-reset').textContent=Math.round(zoom*100)+'%';draw()}
let observer;function setupCanvas(){const canvas=$('canvas');observer?.disconnect();observer=new ResizeObserver(draw);observer.observe(canvas.parentElement);canvas.onpointerdown=e=>{const p=point(e),o=[...current.objects].reverse().find(o=>p.x>=o.x&&p.x<=o.x+o.w&&p.y>=o.y&&p.y<=o.y+o.h);selected=o?.id||null;renderObjects();renderInspector();if(o){snapshot();drag={o,dx:p.x-o.x,dy:p.y-o.y};canvas.setPointerCapture(e.pointerId)}draw()};canvas.onpointermove=e=>{if(!drag)return;const p=point(e);drag.o.x=Math.round((p.x-drag.dx)/16)*16;drag.o.y=Math.round((p.y-drag.dy)/16)*16;draw()};const finish=()=>{if(drag){drag=null;changed()}};canvas.onpointerup=finish;canvas.onpointercancel=finish;canvas.onlostpointercapture=finish}
function point(e){const r=$('canvas').getBoundingClientRect();return{x:(e.clientX-r.left)/zoom,y:(e.clientY-r.top)/zoom}}
function draw(){if(!current||!$('canvas'))return;const c=$('canvas'),r=c.getBoundingClientRect(),dpr=window.devicePixelRatio||1;c.width=Math.round(r.width*dpr);c.height=Math.round(r.height*dpr);const ctx=c.getContext('2d');ctx.scale(dpr,dpr);ctx.fillStyle='#202027';ctx.fillRect(0,0,r.width,r.height);ctx.strokeStyle='#303039';ctx.lineWidth=1;const step=32*zoom;for(let x=0;x<r.width;x+=step){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,r.height);ctx.stroke()}for(let y=0;y<r.height;y+=step){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(r.width,y);ctx.stroke()}ctx.scale(zoom,zoom);for(const o of current.objects){ctx.fillStyle=o.color;if(o.type==='coin'){ctx.beginPath();ctx.ellipse(o.x+o.w/2,o.y+o.h/2,o.w/2,o.h/2,0,0,Math.PI*2);ctx.fill()}else if(o.type==='hazard'){ctx.beginPath();ctx.moveTo(o.x,o.y+o.h);ctx.lineTo(o.x+o.w/2,o.y);ctx.lineTo(o.x+o.w,o.y+o.h);ctx.closePath();ctx.fill()}else ctx.fillRect(o.x,o.y,o.w,o.h);if(o.id===selected){ctx.strokeStyle='#e4cef9';ctx.lineWidth=1.5/zoom;ctx.strokeRect(o.x-3,o.y-3,o.w+6,o.h+6)}}}
$('#create-form').onsubmit=e=>{e.preventDefault();try{const p=createProject($('#project-name').value,$('#template').value);$('#create').close();$('#create-form').reset();openProject(p);save()}catch(e){toast(e.message)}};
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('#import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error('Project files must be smaller than 5 MB.');const p=validateProject(JSON.parse(await file.text()));p.id=crypto.randomUUID();openProject(p);save();toast('Project imported.')}catch(error){toast(error.message)}e.target.value=''};
for(const selector of ['#ai','#motion'])$(selector).onchange=()=>{const prefs={ai:$('#ai').checked,motion:$('#motion').checked};document.body.classList.toggle('reduce-motion',prefs.motion);try{localStorage.setItem('playform.preferences',JSON.stringify(prefs))}catch{toast('Preferences could not be saved.')}};
document.addEventListener('keydown',e=>{if(!current||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey)}});renderHome();
